<?php
require __DIR__.'/../config/database.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT * FROM users WHERE id=? AND role='user'");$q->execute([$id]);$u=$q->fetch();if(!$u){http_response_code(404);exit('Không tìm thấy người dùng.');}
$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE user_id=?');$q->execute([$id]);$bookingCount=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE b.user_id=? AND p.status='paid'");$q->execute([$id]);$paidTotal=(float)$q->fetchColumn();
$q=$pdo->prepare("SELECT b.id,b.booking_date,b.status,b.total_amount,c.name court_name FROM bookings b JOIN courts c ON c.id=b.court_id WHERE b.user_id=? ORDER BY b.id DESC LIMIT 10");$q->execute([$id]);$bookings=$q->fetchAll();$q=$pdo->prepare('SELECT r.rating,r.comment,r.created_at,c.name court_name FROM reviews r JOIN courts c ON c.id=r.court_id WHERE r.user_id=? ORDER BY r.id DESC LIMIT 10');$q->execute([$id]);$reviews=$q->fetchAll();$pageTitle='Chi tiết người dùng';require __DIR__.'/../includes/header.php';require __DIR__.'/_nav.php';
?><h1 class="h3"><?= e($u['full_name']) ?></h1><div class="card card-body mb-3"><p><?= e($u['email']) ?> · <?= e($u['phone']??'Chưa cung cấp số điện thoại') ?></p><p>Tạo tài khoản: <?= e(date('d/m/Y',strtotime($u['created_at']))) ?> · <?= $bookingCount ?> booking · Đã thanh toán: <?= money($paidTotal) ?></p><a class="btn btn-success align-self-start" href="<?= e(app_url('admin/messages.php?user_id='.(int)$u['id'])) ?>">Nhắn khách hàng</a></div><h2 class="h5">Booking gần đây</h2><div class="table-responsive"><table class="table bg-white"><thead><tr><th>Mã</th><th>Sân</th><th>Ngày</th><th>Trạng thái</th><th>Tiền</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><a href="<?= e(app_url('admin/booking_detail.php?id='.(int)$b['id'])) ?>">#<?= (int)$b['id'] ?></a></td><td><?= e($b['court_name']) ?></td><td><?= e(date('d/m/Y',strtotime($b['booking_date']))) ?></td><td><?= e(booking_status_label($b['status'])) ?></td><td><?= money($b['total_amount']) ?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="h5 mt-4">Đánh giá đã viết</h2><?php foreach($reviews as $r): ?><div class="card card-body mb-2"><strong><?= e($r['court_name']) ?> · <?= (int)$r['rating'] ?>/5</strong><span><?= e($r['comment']??'') ?></span></div><?php endforeach; ?></section></div><?php require __DIR__.'/../includes/footer.php'; ?>
